def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1

    opp_d = n - opp_c
    my_d = n - my_c
    opp_rate = opp_c / n

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    recent8 = history[-8:] if n >= 8 else history
    recent_opp_d8 = sum(1 for _, b in recent8 if b == 'D')

    recent10 = history[-10:] if n >= 10 else history
    recent_opp_c10 = sum(1 for _, b in recent10 if b == 'C')

    forgive = 0
    punish = 0
    recover = 0
    rec_samples = 0

    for i in range(1, n):
        prev_my, prev_opp = history[i - 1]
        curr_my, curr_opp = history[i]

        if prev_opp == 'C' and prev_my == 'D':
            if curr_opp == 'C':
                forgive += 1
            else:
                punish += 1

        if prev_my == 'C' and prev_opp == 'D':
            rec_samples += 1
            if curr_opp == 'C':
                recover += 1

    exploit = False
    if n >= 10 and punish == 0:
        if forgive >= 2:
            exploit = True
        elif forgive == 1 and recent_opp_c10 >= 8:
            exploit = True

    if exploit:
        return 'D'

    if my_last == 'C' and opp_last == 'C':
        if n == 20 and opp_c == n and my_c == n and forgive + punish == 0:
            return 'D'

        if opp_rate < 0.35:
            if rng.random() < 0.75:
                return 'D'
            return 'C'

        if recent_opp_d8 >= 6:
            if rng.random() < 0.6:
                return 'D'
            return 'C'

        return 'C'

    if my_last == 'D' and opp_last == 'C':
        return 'C'

    if my_last == 'C' and opp_last == 'D':
        if n >= 90:
            return 'D'

        streak_limit = 4 if my_d == 0 else 5
        if (
            opp_d_streak >= streak_limit
            or opp_c <= 2
            or opp_rate <= 0.45
            or recent_opp_d8 >= 6
        ):
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            return 'C'

        if recover > 0 and rec_samples > 0 and recover * 2 >= rec_samples:
            return 'C'

        if opp_rate >= 0.65:
            return 'C'

        return 'D'

    if n >= 90:
        return 'D'

    if (
        opp_d_streak >= 5
        or opp_c <= 2
        or opp_rate <= 0.45
        or recent_opp_d8 >= 7
    ):
        return 'D'

    if recover > 0 or opp_rate >= 0.60:
        return 'C'

    if recent_opp_c10 >= 5:
        return 'C'

    if rng.random() < 0.4:
        return 'C'

    return 'D'
